mapper.select:
/* egovframework.smartcity.mapper.FacilityMapper.selectFacilityList */ SELECT FAC_ID AS facId, FAC_NAME AS facName, FAC_TYPE AS facType, DISTRICT AS district, LOCATION_ADDR AS locationAddr, LATITUDE AS latitude, LONGITUDE AS longitude, TO_CHAR(INSTALL_DATE, 'YYYY-MM-DD') AS installDate, OP_STATUS AS opStatus, MANAGE_DEPT AS manageDept, MANAGER_NAME AS managerName, MANAGER_PHONE AS managerPhone, TO_CHAR(LAST_INSP_DATE, 'YYYY-MM-DD') AS lastInspDate, REMARKS AS remarks FROM TB_FACILITY
AND DISTRICT = #{district}
AND FAC_TYPE = #{facType}
AND OP_STATUS = #{status}
ORDER BY FAC_ID ASC
